-- The 11 XML mappers of NGC (xmlHandler/mapper/implementation) as MAPPER tags, with the event types each one handles.
-- Event lists come from the rule engine's TargetEventClassification decision table (classification = mapper.eventType()).
-- 'policy' was never an NGC mapper; it stays for existing references but is hidden from pick-lists.

UPDATE tag SET active = FALSE WHERE category = 'MAPPER' AND code = 'policy';

UPDATE tag SET label = 'Policy Page', description = 'PolicyPageXmlMapper (classification POLICYPAGE); 3 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'policy-page';
UPDATE tag SET label = 'Anniversary', description = 'AnniversaryXmlMapper (classification ANNIVERSARY); 3 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'anniversary';
UPDATE tag SET label = 'New Business letters', description = 'NewBusinessLettersXmlMapper (classification NEWBUSINESS_LETTER); 13 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'new-business';
UPDATE tag SET label = 'Generic letters', description = 'GenericLettersXmlMapper (classification GENERIC_LETTER); 75 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'generic-letter';
UPDATE tag SET label = 'Automated letters', description = 'AutomatedLettersXmlMapper (classification AUTOMATED_LETTER); 32 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'automated-letter';
UPDATE tag SET label = 'NIGO letters', description = 'NigoLettersXmlMapper (classification NIGO_LETTER); 46 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'nigo-letter';
UPDATE tag SET label = 'Agent letters', description = 'AgentLettersXmlMapper (classification AGENT_LETTER); 3 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'agent-letter';
UPDATE tag SET label = 'Suitability decline letters', description = 'SuitabilityDeclineLettersXmlMapper (classification SUITABILITY_LETTER); 2 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'suitability-letter';
UPDATE tag SET label = 'Scheduled pages', description = 'ScheduledPagesXmlMapper (classification SCHEDULED_PAGES); 2 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'scheduled-pages';
UPDATE tag SET label = 'Financial confirmation', description = 'FinancialConfirmXmlMapper (classification FINANCIALCONFIRM); 3 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'financial-confirm';
UPDATE tag SET label = 'Adhoc letters', description = 'AdhocLettersXmlMapper (classification ADHOC_LETTER); 1 event types', active = TRUE, updated_at = CURRENT_TIMESTAMP WHERE category = 'MAPPER' AND code = 'adhoc-letter';

-- Which event types each mapper handles (so the UI can suggest a mapper from an event type and show what a mapper covers).
CREATE TABLE mapper_event (
    tag_id     BIGINT       NOT NULL REFERENCES tag(id),
    event_type VARCHAR(160) NOT NULL,
    PRIMARY KEY (tag_id, event_type)
);
CREATE INDEX ix_mapper_event_type ON mapper_event(event_type);

